// src/cache/overlay.mjs
//
// The `Overlay` is the view of the facts that are *about* a V8 build but are
// not object offsets: the C++ enums, the FunctionKind groups, the code-cache
// header's content, and the three layouts V8 declares in C++ rather than in
// Torque.
//
// History, because the name no longer matches the mechanism
// ---------------------------------------------------------
// This used to load `layouts-overlay/<v8Version>.json`, a companion file
// generated by tools/layoutpatch to paper over five gaps in profilegen:
// three ScopeInfo fields its Torque parser dropped, the C++-only enums
// (FunctionKind, FunctionSyntaxKind), the enums whose Torque declaration order
// is not their C++ value (LanguageMode, ElementsKind), the code-cache magic
// base and SourceHash bit widths, and the ContextSlot enum.
//
// profilegen now derives all of those itself (see docs/PROFILEGEN.md and
// ARCHITECTURE.md 9.9), so there is nothing left to patch: this file builds the
// same view out of `profiles/<tag>/layouts.json` and `constants.json`. The
// shape of `Overlay` is unchanged, so every caller keeps working; what changed
// is that the data comes from the profile instead of from a second file, and a
// profile that is missing any of it now fails to generate rather than loading
// and quietly decoding the wrong slots.
//
// `loadOverlayFile` is kept for reading a layoutpatch file directly, which is
// how the two independent derivations can be compared. Nothing in the decode
// path uses it.
//
// This file contains no V8 value of its own: it reads, validates and indexes.

import fs from 'node:fs';
import path from 'node:path';
import { loadProfileForVersion } from '../profile/index.mjs';

export class OverlayError extends Error {}

const REQUIRED = ['v8Version', 'classes', 'enums', 'functionKindGroups', 'codeCache', 'snapshotSpaces'];

/**
 * The key under which the Torque `generates` constant map is exposed.
 *
 * `LayoutResolver` collects `generatesConsts` from every entry of
 * `data.classes`, and reads a class's field program through `classFields(name)`.
 * Holding the constant map under a key that is not a class name keeps the
 * constants available while leaving `classFields` undefined for every real
 * class -- which is the point: the field program now comes from layouts.json
 * alone.
 */
const TORQUE_CONSTANTS_KEY = '$torqueConstants';

export class Overlay {
  constructor(file, data) {
    this.file = file;
    this.data = data;
    this.version = data.v8Version;
  }

  /**
   * The patched field program for a class, or null when the profile suffices
   * -- which, since the profilegen back-port, is always.
   */
  classFields(name) {
    const c = this.data.classes[name];
    return c && c.fields ? c.fields : null;
  }

  hasClass(name) { return Boolean(this.data.classes[name]); }

  enumMembers(name) {
    const e = this.data.enums[name];
    if (!e) throw new OverlayError(`${this.version}: no enum ${name} in ${this.file}`);
    return e.members;
  }

  /**
   * Inclusive ordinal ranges for a FunctionKind predicate from
   * src/objects/function-kind.h, e.g. 'IsGeneratorFunction'.
   */
  kindGroup(predicate) {
    const g = this.data.functionKindGroups[predicate];
    if (!g) {
      const have = Object.keys(this.data.functionKindGroups).join(', ');
      throw new OverlayError(`${this.version}: no FunctionKind group ${predicate} in ${this.file} (have: ${have})`);
    }
    return g;
  }

  /** Does `kindOrdinal` fall in the predicate's ranges? */
  kindIs(predicate, kindOrdinal) {
    return this.kindGroup(predicate).some(([lo, hi]) => kindOrdinal >= lo && kindOrdinal <= hi);
  }

  /** Reverse index of an enum, built once. */
  #reverse(enumName) {
    this._rev ??= new Map();
    let idx = this._rev.get(enumName);
    if (!idx) {
      idx = new Map();
      for (const [k, v] of Object.entries(this.data.enums[enumName]?.members ?? {})) if (!idx.has(v)) idx.set(v, k);
      this._rev.set(enumName, idx);
    }
    return idx;
  }

  /** Name of a FunctionKind ordinal, for reporting. */
  functionKindName(ordinal) { return this.#reverse('FunctionKind').get(ordinal) ?? null; }

  functionSyntaxKindName(ordinal) { return this.#reverse('FunctionSyntaxKind').get(ordinal) ?? null; }

  /** Memoised `kindIs`, since every SharedFunctionInfo asks the same questions. */
  kindFlags(kindOrdinal) {
    this._kindFlags ??= new Map();
    let f = this._kindFlags.get(kindOrdinal);
    if (!f) {
      f = {};
      for (const pred of Object.keys(this.data.functionKindGroups)) f[pred] = this.kindIs(pred, kindOrdinal);
      this._kindFlags.set(kindOrdinal, f);
    }
    return f;
  }

  get codeCache() { return this.data.codeCache; }
  get snapshotSpaces() { return this.data.snapshotSpaces; }

  snapshotSpaceName(index) {
    for (const [k, v] of Object.entries(this.data.snapshotSpaces)) if (v === index) return k;
    return null;
  }

  summary() {
    const d = this.data.diagnostics ?? {};
    return [
      `build facts for ${this.version} from ${this.file}`,
      `  source: ${d.source ?? 'layouts-overlay file'}`,
      `  classes patched: ${(d.classesPatched ?? []).join(', ') || '(none)'}`,
      `  FunctionKind members ${Object.keys(this.data.enums.FunctionKind?.members ?? {}).length}, `
      + `groups ${Object.keys(this.data.functionKindGroups).length}`,
      `  members whose Torque declaration order is not their C++ value: ${(this.data.enumDisagreements ?? []).length}`,
      `  pinned sources recorded: ${(this.data.sources ?? []).length}`,
    ].join('\n');
  }
}

/** Everything the Overlay view needs, read out of one profile. */
function viewFromProfile(profile) {
  const layouts = profile.tables.layouts ?? {};
  const missing = [];
  const need = (cond, what) => { if (!cond) missing.push(what); };
  need(layouts.enums?.FunctionKind?.members, 'layouts.json -> enums.FunctionKind');
  need(layouts.enums?.FunctionSyntaxKind?.members, 'layouts.json -> enums.FunctionSyntaxKind');
  need(layouts.enums?.SnapshotSpace?.members, 'layouts.json -> enums.SnapshotSpace');
  need(layouts.functionKindGroups && Object.keys(layouts.functionKindGroups).length, 'layouts.json -> functionKindGroups');
  need(layouts.cppLayouts && Object.keys(layouts.cppLayouts).length, 'layouts.json -> cppLayouts');
  need(profile.constants?.codeCacheHeader?.magicBase !== undefined, 'constants.json -> codeCacheHeader.magicBase');
  need(profile.constants?.codeCacheHeader?.sourceHash, 'constants.json -> codeCacheHeader.sourceHash');
  if (missing.length) {
    throw new OverlayError(
      `profile ${profile.dir} (V8 ${profile.version}) does not carry the build facts this layer needs:\n  `
      + missing.join('\n  ')
      + '\nRegenerate it with a current profilegen:\n'
      + `  node tools/profilegen/index.mjs --tag ${profile.version} --tagged-size ${profile.taggedSize} --out <dir>\n`
      + 'A profilegen older than 1.1.0 did not derive these; see ARCHITECTURE.md 9.6, 9.9 and 10.7.');
  }

  const cc = profile.constants.codeCacheHeader;
  const torqueConstants = {};
  for (const [name, rec] of Object.entries(layouts.torqueConstants ?? {})) torqueConstants[name] = rec.generates;

  return {
    v8Version: profile.version,
    generator: { name: 'src/cache/overlay.mjs', version: '2.0.0', from: 'profile' },
    classes: {
      // No class is patched any more. The one thing carried here is the Torque
      // `const X: constexpr T generates 'Y'` map, which a layout program's
      // count expression is written in terms of.
      [TORQUE_CONSTANTS_KEY]: { name: TORQUE_CONSTANTS_KEY, generatesConsts: torqueConstants },
    },
    enums: layouts.enums,
    functionKindGroups: layouts.functionKindGroups,
    enumDisagreements: layouts.enumDisagreements ?? [],
    codeCache: {
      magicBase: cc.magicBase,
      magicRule: cc.magicRule,
      sourceHash: cc.sourceHash,
      checksum: cc.checksum,
    },
    snapshotSpaces: layouts.enums.SnapshotSpace.members,
    cppLayouts: layouts.cppLayouts,
    diagnostics: {
      source: `${profile.dir} (profilegen ${profile.meta?.generator?.version ?? '?'})`,
      classesPatched: [],
      torqueConstants: Object.keys(torqueConstants).length,
    },
    sources: profile.meta?.sources ?? [],
  };
}

/**
 * The build facts for a profile.
 *
 * @param {string} v8Version
 * @param {{profile?: object, profilesRoot?: string, root?: string, file?: string}} opts
 *   `profile` -- an already loaded profile (preferred: no second disk read).
 *   `profilesRoot` -- where to find one if `profile` is not given.
 *   `file`/`root` -- read a tools/layoutpatch overlay file instead, for
 *   comparing the two independent derivations.
 */
export function loadOverlay(v8Version, opts = {}) {
  if (opts.file || opts.root) return loadOverlayFile(v8Version, opts);
  const profile = opts.profile ?? loadProfileForVersion(v8Version, { root: opts.profilesRoot ?? 'profiles', strict: opts.strict ?? false });
  if (profile.version !== v8Version) {
    throw new OverlayError(`profile ${profile.dir} declares V8 ${profile.version}, asked for ${v8Version}`);
  }
  return new Overlay(profile.dir, viewFromProfile(profile));
}

/** Read a tools/layoutpatch overlay file. Not used by the decode path. */
export function loadOverlayFile(v8Version, opts = {}) {
  const file = opts.file ?? path.join(opts.root ?? 'layouts-overlay', `${v8Version}.json`);
  if (!fs.existsSync(file)) {
    throw new OverlayError(
      `no layout overlay file for V8 ${v8Version} at ${file}.\n`
      + `Generate it with: node tools/layoutpatch/index.mjs --tag ${v8Version}\n`
      + 'Note that the decode path no longer needs one: profilegen derives these facts itself, '
      + 'and layoutpatch is kept only as an independent cross-check.');
  }
  let data;
  try { data = JSON.parse(fs.readFileSync(file, 'utf8')); }
  catch (e) { throw new OverlayError(`${file} is not valid JSON: ${e.message}`); }
  for (const k of REQUIRED) {
    if (data[k] === undefined) throw new OverlayError(`${file}: missing ${k}`);
  }
  if (data.v8Version !== v8Version) {
    throw new OverlayError(`${file}: declares v8Version ${data.v8Version}, loaded as ${v8Version}`);
  }
  for (const [name, cls] of Object.entries(data.classes)) {
    const issues = cls.crossCheck?.issues ?? [];
    if (issues.length) {
      throw new OverlayError(
        `${file}: class ${name} failed its own cross-check against layouts.json:\n  ${issues.join('\n  ')}\n`
        + `Regenerate with: node tools/layoutpatch/index.mjs --tag ${v8Version}`);
    }
  }
  return new Overlay(file, data);
}

export default { loadOverlay, loadOverlayFile, Overlay, OverlayError };
